const text = $input.first().json.result.content[0].text;
const data = JSON.parse(text);
const g = (data.data ? data.data.goalItemById : data.goalItemById) || {};
const subs = g.subTasks || [];
const now = new Date(); const pad = x => String(x).padStart(2,'0');
const today = pad(now.getDate())+'-'+pad(now.getMonth()+1)+'-'+now.getFullYear();
return [{ json: {
  idea: g.body || '',
  goalId: $('Webhook').first().json.query.goal_id,
  date: g.date || today,
  period: g.period || 'day',
  existingTitles: subs.map(s => String(s.body || '').trim())
}}];

let researchText='', citations=[];
try {
  const r = $('Research Metrics').first().json;
  researchText = (r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '';
  citations = r.citations || r.search_results || [];
} catch (e) {}
if (!researchText) researchText = '(no external research returned; do NOT invent precise statistics - if you cite a number, label it as an approximate, widely-known figure)';
return [{ json: { researchText: String(researchText).slice(0,6000), citations } }];

const extractJson = (s) => {
  s = String(s || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(s); } catch (e) {}
  const i = s.indexOf('{');
  if (i < 0) return null;
  let depth = 0, inStr = false, esc = false;
  for (let k = i; k < s.length; k++) {
    const ch = s[k];
    if (esc) { esc = false; continue; }
    if (inStr) { if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (!depth) { try { return JSON.parse(s.slice(i, k + 1)); } catch (e) { return null; } } }
  }
  return null;
};

let blog = null;
try { const c = $('Generate Blog').first().json; blog = extractJson(c && c.choices ? c.choices[0].message.content : ''); } catch (e) {}
const blogOk = !!(blog && blog.title && Array.isArray(blog.sections) && blog.sections.length >= 4);
return [{ json: { blogOk } }];

const extractJson = (s) => {
  s = String(s || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(s); } catch (e) {}
  const i = s.indexOf('{');
  if (i < 0) return null;
  let depth = 0, inStr = false, esc = false;
  for (let k = i; k < s.length; k++) {
    const ch = s[k];
    if (esc) { esc = false; continue; }
    if (inStr) { if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (!depth) { try { return JSON.parse(s.slice(i, k + 1)); } catch (e) { return null; } } }
  }
  return null;
};

let blog = null;
try { const c = $('Generate Blog').first().json; blog = extractJson(c && c.choices ? c.choices[0].message.content : ''); } catch (e) {}
if (!(blog && blog.title && Array.isArray(blog.sections) && blog.sections.length >= 4)) {
  try { const c2 = $('Generate Blog Paid').first().json;
    blog = extractJson(c2 && c2.choices ? c2.choices[0].message.content : '') || blog; } catch (e) {}
}
blog = blog || {};
const arch = blog.architecture || {};
let diagramUrl = '';
const mer = String(arch.mermaid || '').trim();
if (mer) {
  const b64 = Buffer.from(mer, 'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
  diagramUrl = 'https://mermaid.ink/img/' + b64;
}
const kt = Array.isArray(blog.key_takeaways) ? ('- ' + blog.key_takeaways.join('\n- ')) : '';
// dynamic narrative sections (writer-chosen headings) - the channels read this as their source of truth
const secs = Array.isArray(blog.sections) ? blog.sections : [];
const blogSource = [
  'TITLE: ' + (blog.title || ''),
  'HOOK: ' + (blog.hook || ''),
  ...secs.map(s => ((s && s.heading) ? String(s.heading) : 'SECTION') + ':\n' + ((s && s.body) || '')),
  'KEY TAKEAWAYS:\n' + kt
].join('\n\n').slice(0,7000);
const heroPrompt = blog.hero_image_prompt || ('Modern professional editorial flat illustration about: ' + ($('Parse Goal').first().json.idea || ''));
return [{ json: { blog, diagramUrl, blogSource, heroPrompt } }];

const resp = $input.first().json;
let b64='', mime='image/png', hasImage=false;
const msg = resp && resp.choices && resp.choices[0] && resp.choices[0].message;
if (msg && Array.isArray(msg.images) && msg.images.length) {
  const u = (msg.images[0].image_url && msg.images[0].image_url.url) || msg.images[0].url || '';
  const mm = u.match(/^data:(image\/[a-zA-Z+]+);base64,(.+)$/);
  if (mm) { mime=mm[1]; b64=mm[2]; hasImage=true; }
}
const o = { json: { hasImage, mime }, pairedItem: 0 };
if (hasImage) { const buf = Buffer.from(b64,'base64'); o.binary = { data: await this.helpers.prepareBinaryData(buf,'cmo-hero.png',mime) }; }
return [o];

