const idea = $('Parse Goal').first().json.idea;
const pb = $('Parse Blog').first().json || {};
const blog = pb.blog || {};
const diagramUrl = pb.diagramUrl || '';
let heroUrl = '';
try { const id = ($('Upload to Drive').first().json || {}).id; if (id) heroUrl = 'https://lh3.googleusercontent.com/d/' + id + '=w1600'; } catch (e) {}

const tagify = a => Array.isArray(a) ? a.map(h => (String(h)[0]==='#'?h:'#'+h)).join(' ') : '';
const parseNode = nm => { try { const r = $(nm).first().json; return JSON.parse(r && r.choices ? r.choices[0].message.content : '{}'); } catch (e) { return {}; } };

// ---- Blog section (End-compatible markers: ## Blog, **title**, Caption:, CTA:) ----
// dynamic narrative: writer-chosen section headings; the architecture diagram renders inside the
// section the writer nominated via architecture.section_heading (fallback: after the middle section)
const arch = blog.architecture || {};
const bl = ['## Blog'];
if (blog.title) bl.push('**' + blog.title + '**');
if (heroUrl) bl.push('![hero](' + heroUrl + ')');
if (blog.hook) bl.push(blog.hook);
const secs = Array.isArray(blog.sections) ? blog.sections : [];
const archHead = String(arch.section_heading || '').trim().toLowerCase();
let diagramPlaced = false;
secs.forEach((s, i) => {
  if (!s || (!s.heading && !s.body)) return;
  if (s.heading) bl.push('### ' + s.heading);
  if (s.body) bl.push(s.body);
  const isArchSec = archHead && String(s.heading || '').trim().toLowerCase() === archHead;
  const fallbackSlot = !archHead && i === Math.min(secs.length - 1, Math.floor(secs.length / 2));
  if (diagramUrl && !diagramPlaced && (isArchSec || fallbackSlot)) {
    bl.push('![architecture](' + diagramUrl + ')'); diagramPlaced = true;
  }
});
if (diagramUrl && !diagramPlaced) bl.push('![architecture](' + diagramUrl + ')');
if (Array.isArray(blog.sources) && blog.sources.length) bl.push('Sources: ' + blog.sources.join(' | '));
if (blog.meta_description) bl.push('Caption: ' + blog.meta_description);
const btags = tagify(blog.hashtags); if (btags) bl.push(btags);
bl.push('CTA: Read the full post on the blog.');

const CH = [
  { node:'Explainer Video', label:'Explainer Video',      video:true  },
  { node:'Instagram Reel',  label:'Instagram Reel',       video:true  },
  { node:'YouTube Reel',    label:'YouTube Reel',         video:true  },
  { node:'Facebook Post',   label:'Facebook Post',        video:false },
  { node:'X Post',          label:'X Post + Engagement',  video:false },
  { node:'TikTok',          label:'TikTok Post',          video:true  },
  { node:'LinkedIn Post',   label:'LinkedIn Post',        video:false },
];

const titles = ['Blog'];
const sections = [bl.join('\n\n')];
for (const ch of CH) {
  titles.push(ch.label);
  const c = parseNode(ch.node);
  const L = ['## ' + ch.label];
  if (c.headline) L.push('**' + c.headline + '**');
  if (ch.video) {
    if (c.script) L.push('Script:\n' + c.script);
    const bp = Array.isArray(c.broll_prompts) ? c.broll_prompts : (c.broll_prompts ? [c.broll_prompts] : []);
    if (bp.length) L.push('B-roll:\n' + bp.map((p,i) => (i+1) + '. ' + p).join('\n'));
  } else {
    if (c.body) L.push(c.body);
  }
  if (c.caption) L.push('Caption: ' + c.caption);
  const t = tagify(c.hashtags); if (t) L.push(t);
  if (c.cta) L.push('CTA: ' + c.cta);
  sections.push(L.join('\n\n'));
}

const contributionMd = '# Campaign plan\n\nIdea: ' + idea
  + '\n\nThe blog is the source of truth; every channel below is derived from it. Review the scripts, then tick the '
  + 'channels you want - assets are generated only for ticked channels.\n\n'
  + sections.join('\n\n---\n\n');

return [{ json: {
  goalId: $('Parse Goal').first().json.goalId,
  date: $('Parse Goal').first().json.date,
  period: $('Parse Goal').first().json.period,
  idea, blogTitle: blog.title || '', diagramUrl, heroUrl, titles, contributionMd
}}];

const j = $('Build Plan').first().json;
const apiKey = $('API Key').first().json.apiKey;
const existing = new Set(($('Parse Goal').first().json.existingTitles) || []);
const MCP = 'https://aicivz8c3l.execute-api.ap-south-1.amazonaws.com/dev/mcp/call';
const Q = 'mutation AddSub($taskId: ID!, $date: String!, $period: String!, $body: String) ' +
          '{ addSubTaskItem(taskId: $taskId, date: $date, period: $period, body: $body, isComplete: false) { id } }';
const results = [];
for (const title of (j.titles || [])) {
  if (existing.has(title)) { results.push('skip:' + title); continue; }
  try {
    await this.helpers.httpRequest({ method:'POST', url:MCP,
      headers:{ 'Content-Type':'application/json', 'X-API-Key':apiKey },
      body:{ jsonrpc:'2.0', method:'tools/call', id:1, params:{ name:'graphql_query',
        arguments:{ query:Q, variables:{ taskId:j.goalId, date:j.date, period:j.period, body:title } } } }, json:true });
    results.push('ok:' + title);
  } catch (e) { results.push('err:' + title); }
  await new Promise(r => setTimeout(r, 400));
}
return [{ json: { created: results.filter(r => r.startsWith('ok')).length, results,
  goalId: j.goalId, contributionMd: j.contributionMd } }];

